# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs):
    return [v * v for v in xs[1:]]

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(emit(intake(fold(gather(raw)))))

